import heapq


def _dependency_solver(data, name_order, preference):
    packages = data["packages"]
    names = sorted(packages, reverse=(name_order == "descending"))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = []
    for name in names:
        rows = [row for row in packages[name]
                if row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        choices.append([None] + rows)

    best_vector = None
    best_versions = None
    for selection in product(*choices):
        selected = {name: row for name, row in zip(names, selection)
                    if row is not None}
        if any(root not in selected or not bounds[0] <= selected[root]["version"] <= bounds[1]
               for root, bounds in data["roots"].items()):
            continue

        edges = {}
        valid = True
        for name, row in selected.items():
            edges[name] = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = selected.get(dep["name"])
                if target is None or not dep["min"] <= target["version"] <= dep["max"]:
                    valid = False
                    break
                edges[name].append(dep["name"])
            if not valid:
                break
        if not valid:
            continue

        # The installation must be precisely the closure reachable from roots.
        closure = set()
        pending = list(data["roots"])
        while pending:
            name = pending.pop()
            if name in closure:
                continue
            closure.add(name)
            pending.extend(edges[name])
        if closure != set(selected):
            continue

        visiting, finished = set(), set()

        def acyclic(name):
            if name in visiting:
                return False
            if name in finished:
                return True
            visiting.add(name)
            if any(not acyclic(other) for other in edges[name]):
                return False
            visiting.remove(name)
            finished.add(name)
            return True

        if not all(acyclic(name) for name in closure):
            continue

        vector = tuple(selected[name]["version"] if name in selected else -1
                       for name in names)
        better = (best_vector is None or
                  (vector > best_vector if preference == "maximum" else vector < best_vector))
        if better:
            best_vector = vector
            best_versions = {name: selected[name]["version"] for name in names
                             if name in selected}

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _component_01(data):
    return _dependency_solver(data, "ascending", "maximum")


def _component_02(data):
