def _round_fraction(numerator, rounding):
    if rounding == "half_up":
        return (numerator + 5000) // 10000
    return numerator // 10000


def _component_06(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round_fraction(raw * (10000 - discount), data["rounding"])
        tax = _round_fraction(net * event.get("tax_bp", 0), data["rounding"])
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_07(data):
    blocked = set(data.get("blocked", []))
    jobs = [job for job in data["jobs"] if job["id"] not in blocked]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for group in combinations(jobs, data["k"]):
        ids = {job["id"] for job in group}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in group:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(name, 0) <= high
               for name, (low, high) in quotas.items()):
            continue

        active_ends = []
        overlap = False
        for job in sorted(group, key=lambda item: (item["start"], item["end"], item["id"])):
            active_ends = [end for end in active_ends if end > job["start"]]
            active_ends.append(job["end"])
            if len(active_ends) > 2:
                overlap = True
                break
        if overlap:
            continue

        value = sum(job["value"] for job in group)
        selected_ids = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and selected_ids < best_ids)):
            best_value, best_ids = value, selected_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _component_08(data):
    required = data.get("required", [])
    bits = {node: 1 << index for index, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bits.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    distances = {initial: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]

    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": arrival}

        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                options.append((duration, remaining - 1))
            next_mask = mask | bits.get(edge["v"], 0)
            for duration, next_remaining in options:
                next_arrival = depart + duration
                if next_arrival > data["deadline"]:
                    continue
                next_state = (edge["v"], next_mask, next_remaining)
                if next_arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = next_arrival
                    heapq.heappush(queue, (next_arrival, *next_state))
    return {"arrival": None}


